        if (r, c) == goal:
            path_so_far.append((r, c))
            return True
        grid[r] = grid[r][:c] + '#' + grid[r][c + 1:]
        for dr, dc in dirs:
            nr, nc = (r + dr, c + dc)
            if 0 <= nr < rows and 0 <= nc < cols and (grid[nr][nc] == '.'):
                path_so_far.append((nr, nc))
                if dfs(nr, nc, path_so_far):
                    return True
                path_so_far.pop()
        grid[r] = grid[r][:c] + '.' + grid[r][c + 1:]
        return False
    if grid[start[0]][start[1]] == '.' and grid[goal[0]][goal[1]] == '.':
        path.append(start)
        if dfs(start[0], start[1], path):
