from collections import deque

def solve(n, edges, s, t):
    if s == t:
        return 0

    # Build adjacency list
    adj = [[] for _ in range(n)]
    for u, v, w in edges:
        adj[u].append((v, w))

    # Bellman-Ford algorithm for single-source shortest path
    # It can handle negative weights and detect negative cycles
    # But since weights are non-negative (0 <= w <= 100), we can use it safely

    # Initialize distance array
    dist = [float('inf')] * n
    dist[s] = 0

    # Relax edges up to n-1 times
    for i in range(n-1):
        updated = False
        for u in range(n):
            if dist[u] == float('inf'):
                continue
            for v, w in adj[u]:
                if dist[v] > dist[u] + w:
                    dist[v] = dist[u] + w
                    updated = True
        if not updated:
            break

    return dist[t] if dist[t] != float('inf') else -1
