    for u, v, w in edges:
        graph[u].append((v, w))

    # Bellman-Ford algorithm to find shortest path
    # Initialize distance array
    dist = [float('inf')] * n
    dist[s] = 0

    # Relax edges up to n-1 times
    for i in range(n - 1):
